import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/PowerShell.html","title":"PowerShell","lang":"en-US","frontmatter":{},"git":{"createdTime":1757383554000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":5}]},"readingTime":{"minutes":0.51,"words":153},"filePathRelative":"PowerShell.md"}`),a={name:`PowerShell.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="powershell" tabindex="-1"><a class="header-anchor" href="#powershell"><span>PowerShell</span></a></h1><p><a href="./Windows.html">Windows</a>のシェル。<a href="./技術的なメモ.html">技術的なメモ</a></p><h2 id="こまごまとしたこと" tabindex="-1"><a class="header-anchor" href="#こまごまとしたこと"><span>こまごまとしたこと</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PS&gt; notepad $PROFILE</span>
<span class="line">PS&gt; echo $env:APPDATA</span>
<span class="line">PS&gt; $env:PATH</span>
<span class="line">PS&gt; $env:PATH.Split(&quot;;&quot;)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>久しぶりにPowerShellを使おうとして忘れているもの。 Out-GridView。</p><h2 id="zlocation" tabindex="-1"><a class="header-anchor" href="#zlocation"><span>ZLocation</span></a></h2><p>PowerShellでもautojumpのようなものが欲しいなぁ、とCopilotに聞いてZLocationというのを教えてもらう。<a href="https://github.com/vors/ZLocation" target="_blank" rel="noopener noreferrer">vors/ZLocation: ZLocation is the new Jump-Location</a></p><p>少し試してみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ Install-Module ZLocation -Scope CurrentUser</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>profileに</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Import-Module ZLocation</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="モジュール開発" tabindex="-1"><a class="header-anchor" href="#モジュール開発"><span>モジュール開発</span></a></h2><p><a href="./PSDotenvrc.html">PSDotenvrc</a>を開発するのにこの辺のノウハウが必要になった。</p><ul><li><a href="https://learn.microsoft.com/en-us/powershell/scripting/developer/module/writing-a-windows-powershell-module?view=powershell-7.5" target="_blank" rel="noopener noreferrer">Writing a Windows PowerShell Module - PowerShell - Microsoft Learn</a> モジュールのドキュメント</li></ul><p>Impot-Moduleでディレクトリを指定する。 DllはロードされるとRemove-Moduleしても残ってしまうので、テストは<code>Start-Process pwsh</code> の中でやるのがよい。</p><p>NoNewWindowはなんかターミナルが変になったので使わない。</p><h2 id="powershell上のdirenv代替、psdotenvrc" tabindex="-1"><a class="header-anchor" href="#powershell上のdirenv代替、psdotenvrc"><span>PowerShell上のdirenv代替、PSDotenvrc</span></a></h2><p>結局自分で作ることにした。</p><p><a href="./PSDotenvrc.html">PSDotenvrc</a></p><h2 id="developerpowershell-for-vs2022で使ってるpowershellのバージョンアップ" tabindex="-1"><a class="header-anchor" href="#developerpowershell-for-vs2022で使ってるpowershellのバージョンアップ"><span>DeveloperPowerShell for VS2022で使ってるpowershellのバージョンアップ</span></a></h2><p>マシンによっては5.1とかが使われているのでアップデートする手順。</p><ol><li>choco install powershell-core</li><li>Windows terminalなどのDeveloper PowerShell for VS2022の先頭のpowershell.exeをC:/Program Files/PowerShell/7/pwsh.exeとかに差し替え（パスのコピーで得た値をペーストする）</li></ol><h2 id="patchファイルをつなげるcat的な事" tabindex="-1"><a class="header-anchor" href="#patchファイルをつなげるcat的な事"><span>patchファイルをつなげるcat的な事</span></a></h2><p>cmd.exeを呼ぶのが一番楽か。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ cmd /c &quot;copy /b python3_win.patch+python3_win2.patch+python3_win3.patch python3_win_all.patch&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};